import { describe, it, expect, afterEach } from 'vitest';
import { createFocusReturn } from './focusReturn';

// Click counts: a click generated by Enter or Space on a button reports none,
// a real mouse click reports at least one
const KEYBOARD_CLICK_DETAIL = 0;
const MOUSE_CLICK_DETAIL = 1;

function clickEvent(detail: number): MouseEvent {
  return new MouseEvent('click', { detail, bubbles: true });
}

describe('createFocusReturn', () => {
  let outside: HTMLButtonElement;
  let container: HTMLDivElement;
  let inner: HTMLButtonElement;

  function setup() {
    outside = document.createElement('button');
    container = document.createElement('div');
    inner = document.createElement('button');
    container.appendChild(inner);
    document.body.append(outside, container);
  }

  afterEach(() => {
    outside.remove();
    container.remove();
  });

  it('returns focus to the element it came from on a keyboard dismissal', () => {
    setup();
    const { track, restore } = createFocusReturn();
    track(container);

    outside.focus();
    inner.focus();
    restore(clickEvent(KEYBOARD_CLICK_DETAIL));
    container.remove();

    expect(document.activeElement).toBe(outside);
  });

  it('leaves focus alone on a mouse click', () => {
    setup();
    const { track, restore } = createFocusReturn();
    track(container);

    outside.focus();
    inner.focus();
    restore(clickEvent(MOUSE_CLICK_DETAIL));

    expect(document.activeElement).toBe(inner);
  });

  it('does nothing before it is attached to an element', () => {
    setup();
    const { restore } = createFocusReturn();

    outside.focus();
    inner.focus();
    restore(clickEvent(KEYBOARD_CLICK_DETAIL));

    expect(document.activeElement).toBe(inner);
  });

  it('stops tracking once the action is destroyed', () => {
    setup();
    const { track, restore } = createFocusReturn();
    const action = track(container);

    if (typeof action === 'object') {
      action.destroy?.();
    }
    outside.focus();
    inner.focus();
    restore(clickEvent(KEYBOARD_CLICK_DETAIL));

    expect(document.activeElement).toBe(inner);
  });
});
